  cluster_602: {"id":"cluster_602","version":4,"name":"Barren Shores","description":"No information available","x":-165000.0,"z":95260.0,"environment":"Clear Space","suns":["White Giant"],"planets":[{"name":"Menehune","class":"Terrestrial","geology":"Ocean","atmosphere":"Nitrogen/Oxygen","population":"$POPULATION$","maxPopulation":800000000,"settlements":"Multiple Cities","moons":[{"name":"Yanva","geology":"Barren","atmosphere":"None","population":"None","settlements":"Uninhabited"},{"name":"Urvasi","geology":"Desert","atmosphere":"None","population":"None","settlements":"Uninhabited"}]}],"sectors":["cluster_602_sector001"]},
